import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.DnrXFDHb.js";const d=JSON.parse('{"title":"常用网站","description":"按用途分组整理常用 AI 网站并说明选用时机，给出判断资源可靠性的核对方法与一次模型下载的完整尽调示例。","frontmatter":{"description":"按用途分组整理常用 AI 网站并说明选用时机，给出判断资源可靠性的核对方法与一次模型下载的完整尽调示例。"},"headers":[],"relativePath":"resources/websites.md","filePath":"resources/websites.md","lastUpdated":1788365664000}'),i={name:"resources/websites.md"};function o(n,a,s,h,p,c){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="常用网站" tabindex="-1">常用网站 <a class="header-anchor" href="#常用网站" aria-label="Permalink to &quot;常用网站&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 这份清单按用途分组：先用官方课程补概念，再用平台查模型与论文，最后按工具找官方文档；每个条目附“选用”提示，说明什么时候用、什么时候跳过。下载或引用任何资源前，先核对发布者、模型卡（Model Card）和许可证（License）——外部资源随时可能更新，遇到冲突以官方为准。</p></blockquote><p>本页链接与描述核对于 2026 年 9 月；网站与平台迭代较快，使用前请以官方页面为准。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/basics">大模型入门</a>：本页会反复出现模型卡、幻觉、知识截止这些词，先有印象再读更顺。</li><li>读过 <a href="/tools/common-tools">常用工具</a> 更好——两页分工：那边判断“需要哪类工具”，本页解决“网站怎么选、怎么核对”。</li><li>先接受一个边界：本页只负责“有哪些、怎么选、怎么核对”，具体操作步骤在 <a href="/resources/tutorials">精选教程</a>。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>按用途从本页七组资源里选出当下需要的一两个，而不是全部收藏。</li><li>说出核对一个外部资源的六个检查点：官方性、更新时间、许可证、发布者、社区热度、交叉验证。</li><li>在下载一个模型前，按“发布者 → 模型卡 → 许可证 → 文件与量化 → 社区反馈 → 记录存档”的顺序做一遍尽调。</li><li>解释为什么预印本、Star 数、跑通教程都不能单独作为可信依据。</li><li>用“来源、版本、访问日期、关键配置”四项记录，保证以后能复查。</li></ul><h2 id="ai-与-llm-官方学习" tabindex="-1">AI 与 LLM 官方学习 <a class="header-anchor" href="#ai-与-llm-官方学习" aria-label="Permalink to &quot;AI 与 LLM 官方学习&quot;">​</a></h2><p>这组解决“概念从哪学”：官方出品的系统课程，负责在动手之前把基础概念补齐。</p><h3 id="google-machine-learning" tabindex="-1">Google Machine Learning <a class="header-anchor" href="#google-machine-learning" aria-label="Permalink to &quot;Google Machine Learning&quot;">​</a></h3><p>地址：<a href="https://developers.google.com/machine-learning" target="_blank" rel="noreferrer">https://developers.google.com/machine-learning</a></p><p>用途：</p><ul><li>学习机器学习基础、数据、模型和大语言模型概念。</li><li>通过短课程建立从 Token 到 Transformer 的基础认识。</li><li>适合在阅读框架文档前补齐通用概念。</li></ul><p>选用：零基础第一次系统补概念时用；已经能直接读懂框架文档后，不必回头从头再刷一遍。</p><h3 id="hugging-face-llm-course" tabindex="-1">Hugging Face LLM Course <a class="header-anchor" href="#hugging-face-llm-course" aria-label="Permalink to &quot;Hugging Face LLM Course&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">https://huggingface.co/learn/llm-course/chapter1/1</a></p><p>用途：</p><ul><li>系统学习 Transformer、Tokenizer、推理和微调。</li><li>配合 Hugging Face 模型与数据生态进行实践。</li><li>课程以英文和代码为主，适合掌握本站基础概念后继续学习。</li></ul><p>选用：读完 <a href="/llm/basics">大模型入门</a> 想动手实践时用；还不习惯读英文加代码的话，先把本站中文概念页过完再进。</p><h3 id="hugging-face-agents-course" tabindex="-1">Hugging Face Agents Course <a class="header-anchor" href="#hugging-face-agents-course" aria-label="Permalink to &quot;Hugging Face Agents Course&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/learn/agents-course/en/unit0/introduction" target="_blank" rel="noreferrer">https://huggingface.co/learn/agents-course/en/unit0/introduction</a></p><p>用途：</p><ul><li>学习 Agent、Tool Use、Function Calling 和 Agentic RAG。</li><li>了解常见框架和评估方式。</li><li>内容更新较快，使用时注意课程单元和依赖版本。</li></ul><p>选用：打算自己写 Agent 应用时用；只想先弄懂概念的话，读 <a href="/llm/rag-agent">RAG 与 Agent</a> 就够了。</p><h2 id="模型与数据平台" tabindex="-1">模型与数据平台 <a class="header-anchor" href="#模型与数据平台" aria-label="Permalink to &quot;模型与数据平台&quot;">​</a></h2><p>这组解决“模型从哪来、怎么读说明”：下载前在这里核对模型卡、许可证和推荐参数。</p><h3 id="hugging-face" tabindex="-1">Hugging Face <a class="header-anchor" href="#hugging-face" aria-label="Permalink to &quot;Hugging Face&quot;">​</a></h3><p>地址：<a href="https://huggingface.co" target="_blank" rel="noreferrer">https://huggingface.co</a></p><p>用途：</p><ul><li>查找模型、数据集、演示和官方文档。</li><li>查看模型卡、许可证、文件结构和推荐用法。</li><li>比较不同任务、框架和模型版本。</li></ul><p>下载或调用模型前先核对发布者、许可证、所需文件、量化（Quantization）格式和用途限制。</p><p>选用：找模型、读模型卡的第一站；不该用它做的事是照搬别人的“整合包”——下载前仍要回到原始发布页核对。</p><h3 id="civitai" tabindex="-1">Civitai <a class="header-anchor" href="#civitai" aria-label="Permalink to &quot;Civitai&quot;">​</a></h3><p>地址：<a href="https://civitai.com" target="_blank" rel="noreferrer">https://civitai.com</a></p><p>用途：</p><ul><li>查找 AI 绘画 checkpoint、LoRA、VAE、工作流和示例图。</li><li>查看示例 Prompt、推荐参数和社区反馈。</li></ul><p>这是社区平台，模型质量、来源、许可证和内容分级差异很大，公开使用前要逐项核对。</p><p>选用：找绘画底模、LoRA 和工作流参考时用；作品要公开发布或商用时，不能只依赖这里的社区标签，许可证要回原始发布页逐项确认。</p><h2 id="论文与研究进展" tabindex="-1">论文与研究进展 <a class="header-anchor" href="#论文与研究进展" aria-label="Permalink to &quot;论文与研究进展&quot;">​</a></h2><p>这组解决“新知识从哪追踪”：查找原始论文，判断一个说法有没有出处。</p><h3 id="arxiv" tabindex="-1">arXiv <a class="header-anchor" href="#arxiv" aria-label="Permalink to &quot;arXiv&quot;">​</a></h3><p>地址：<a href="https://arxiv.org" target="_blank" rel="noreferrer">https://arxiv.org</a></p><p>用途：查找 AI、机器学习、自然语言处理和计算机视觉论文预印本（Preprint）。预印本不等于已经同行评审（Peer Review），结论需要结合正式论文、代码和后续研究判断。</p><p>选用：查一个说法的原始出处时用；不适合当入门教材——预印本默认读者已有基础。</p><h3 id="hugging-face-papers" tabindex="-1">Hugging Face Papers <a class="header-anchor" href="#hugging-face-papers" aria-label="Permalink to &quot;Hugging Face Papers&quot;">​</a></h3><p>地址：<a href="https://huggingface.co/papers" target="_blank" rel="noreferrer">https://huggingface.co/papers</a></p><p>用途：按日浏览 AI 论文与社区讨论，跟踪研究方向。原来的 Papers with Code 站点已停止服务并跳转至此；论文是否可靠，仍需结合正式发表版本、代码与后续研究判断。</p><p>选用：每天花几分钟跟踪新方向时用；不适合系统学习，也不要把热门排序当成质量保证。</p><h2 id="rag、agent-与本地模型" tabindex="-1">RAG、Agent 与本地模型 <a class="header-anchor" href="#rag、agent-与本地模型" aria-label="Permalink to &quot;RAG、Agent 与本地模型&quot;">​</a></h2><p>这组解决“应用框架与本地部署的文档在哪”：把本站原理页对应到具体框架的官方文档。</p><h3 id="langchain-文档" tabindex="-1">LangChain 文档 <a class="header-anchor" href="#langchain-文档" aria-label="Permalink to &quot;LangChain 文档&quot;">​</a></h3><p>地址：<a href="https://docs.langchain.com" target="_blank" rel="noreferrer">https://docs.langchain.com</a></p><p>用途：了解模型调用、工具、检索和 Agent 应用结构。框架 API 变化较快，示例代码必须对应当前文档版本。</p><p>选用：动手写 Agent 或 RAG 代码时，对照官方文档查当前版本的 API；不要照抄过时教程里的代码。</p><h3 id="llamaindex-文档" tabindex="-1">LlamaIndex 文档 <a class="header-anchor" href="#llamaindex-文档" aria-label="Permalink to &quot;LlamaIndex 文档&quot;">​</a></h3><p>地址：<a href="https://docs.llamaindex.ai" target="_blank" rel="noreferrer">https://docs.llamaindex.ai</a></p><p>用途：学习文档加载、索引、检索、RAG 和 Agent 数据流程。</p><p>选用：核心需求是“把自有文档接进模型”时优先看；只是想调用模型对话，用不到它。</p><h3 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to &quot;Ollama&quot;">​</a></h3><p>地址：<a href="https://ollama.com" target="_blank" rel="noreferrer">https://ollama.com</a></p><p>用途：查看本地模型运行工具、支持模型和使用文档。下载模型前仍需阅读原始模型许可证和硬件要求。</p><p>选用：想在本地跑模型时，从这里的支持列表和文档入手；它不负责教你选模型——选型回到模型卡和许可证。</p><h2 id="ai-绘画工具与项目" tabindex="-1">AI 绘画工具与项目 <a class="header-anchor" href="#ai-绘画工具与项目" aria-label="Permalink to &quot;AI 绘画工具与项目&quot;">​</a></h2><p>这组解决“绘画工具与模型发布在哪看”：工具、底模与官方公告的第一手来源。</p><h3 id="comfyui" tabindex="-1">ComfyUI <a class="header-anchor" href="#comfyui" aria-label="Permalink to &quot;ComfyUI&quot;">​</a></h3><p>地址：<a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">https://github.com/Comfy-Org/ComfyUI</a></p><p>用途：</p><ul><li>获取节点式 AI 绘画工具和发布说明。</li><li>学习工作流、节点数据流和模型支持情况。</li><li>排查自定义节点和核心版本兼容问题。</li></ul><p>选用：装了 ComfyUI 或遇到节点报错时来查；还没决定用哪个绘画工具的话，先读 <a href="/models/ecosystems">常见模型生态</a> 再动手。</p><h3 id="stability-ai" tabindex="-1">Stability AI <a class="header-anchor" href="#stability-ai" aria-label="Permalink to &quot;Stability AI&quot;">​</a></h3><p>地址：<a href="https://stability.ai" target="_blank" rel="noreferrer">https://stability.ai</a></p><p>用途：了解 Stable Diffusion 相关模型与项目公告。</p><p>选用：确认 Stable Diffusion 系列的官方动态和模型出处时用；找具体模型文件通常还是去 Hugging Face 或 Civitai。</p><h3 id="black-forest-labs" tabindex="-1">Black Forest Labs <a class="header-anchor" href="#black-forest-labs" aria-label="Permalink to &quot;Black Forest Labs&quot;">​</a></h3><p>地址：<a href="https://bfl.ai" target="_blank" rel="noreferrer">https://bfl.ai</a></p><p>用途：了解 FLUX 系列模型与相关发布。</p><p>选用：使用 FLUX 系列时，以这里确认官方版本与许可证；教程里流传的“某个 FLUX 版本”，出处以官方页面为准。</p><h2 id="文档建设" tabindex="-1">文档建设 <a class="header-anchor" href="#文档建设" aria-label="Permalink to &quot;文档建设&quot;">​</a></h2><p>这组解决“本站怎么搭”：想维护自己的知识库，从这里开始。</p><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h3><p>地址：<a href="https://vitepress.dev" target="_blank" rel="noreferrer">https://vitepress.dev</a></p><p>用途：搭建静态文档站、个人知识库和项目教程。</p><p>选用：想自己搭一个像本站这样的知识库时用；只是想写日常笔记，一个 Markdown 编辑器就够了。</p><h2 id="精选教程入口" tabindex="-1">精选教程入口 <a class="header-anchor" href="#精选教程入口" aria-label="Permalink to &quot;精选教程入口&quot;">​</a></h2><p>这组解决“先看哪个教程”：完整清单见 <a href="/resources/tutorials">精选教程</a>，这里只留三个最推荐的入口：</p><ul><li><a href="https://developers.google.com/machine-learning/crash-course/llm" target="_blank" rel="noreferrer">Google LLM 入门课程</a>：建立大模型基础概念。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">Hugging Face LLM Course</a>：继续学习 Transformer 与模型实践。</li><li><a href="https://docs.comfy.org/zh" target="_blank" rel="noreferrer">ComfyUI 官方中文文档</a>：进入 AI 绘画工作流。</li></ul><p>选用：按当前学习路径三选一，走完一条再扩展，不要三条同时开。</p><h2 id="怎么判断一个资源靠不靠谱" tabindex="-1">怎么判断一个资源靠不靠谱 <a class="header-anchor" href="#怎么判断一个资源靠不靠谱" aria-label="Permalink to &quot;怎么判断一个资源靠不靠谱&quot;">​</a></h2><p>本页收录的条目都按下面的标准筛过；更重要的是，你以后遇到本页之外的网站、模型和教程，也可以用同样的六道检查。</p><ol><li><strong>官方优先，并确认“官方”是真的。</strong> 官方文档、模型卡和官方示例错得最少、过期得最慢。但冒名页面和“官网风格”的聚合站不少：确认方法是看域名是否属于发布机构（例如 Google 的课程在 developers.google.com 下）、模型页发布者是否是该机构的官方账号、链接能否从官方 GitHub 仓库或论文主页跳转到达。搜索引擎排第一、被浏览器插件推荐，都不算确认。</li><li><strong>看更新时间。</strong> 文档的“最后更新”日期、仓库的最近提交、课程的版本号，说明内容还活着。AI 领域以月为单位迭代，两年没动的教程即使当时正确，涉及的 API 和模型也多半已经变了。</li><li><strong>看许可证与用途限制。</strong> 开源不等于可以随意商用：LICENSE 文件和模型卡写明能不能商用、要不要署名、有没有附加条款；数据集和绘画素材还可能限制转售或公开分发。微调、量化都不改变原始许可证的约束。拿不准就先当不能用。</li><li><strong>确认发布者身份。</strong> 同一个模型名下，可能有官方原版、官方微调、第三方重打包和来路不明的改名版。优先用发布机构自己账号下的页面；第三方上传的版本，要能说清改了什么、是否获得授权。</li><li><strong>警惕社区热度的局限。</strong> Star 数、点赞和“全网都在转”衡量的是注意力，不是正确性：热度可以靠营销堆起来，热门论文被复现失败也不罕见。热度可以当线索，不能当结论。</li><li><strong>多方交叉验证。</strong> 重要结论至少找两个独立来源：论文看原文而不是转述，参数回到官方文档，教程里的命令和官方 README 对一遍。注意，两个来源互相引用不算独立——很多转述内容追根溯源是同一篇预印本。</li></ol><h2 id="最小推演-给一次模型下载做尽调" tabindex="-1">最小推演：给一次模型下载做尽调 <a class="header-anchor" href="#最小推演-给一次模型下载做尽调" aria-label="Permalink to &quot;最小推演：给一次模型下载做尽调&quot;">​</a></h2><p>下面走一遍完整流程。场景是虚构的：你想给本地写作工具找一个中文小说续写模型，在模型平台搜到 “story-teller-8b”，发布者署名 “story-fan-2026”，下载按钮就在眼前。先别点，按六步走。</p><p>第 1 步，查发布者。点开发布者主页：个人账号，没有组织认证，名下只有这一个模型。回到搜索，发现组织账号 “story-lab” 下有同名模型，模型卡写明这是官方微调版。——改用组织账号的版本，个人重打包版直接排除。</p><p>第 2 步，读模型卡。组织版的模型卡写清：基于哪个基座模型（Base Model）、用了什么训练数据、推荐参数、已知局限。基座怎么决定微调版的能力与授权边界，见 <a href="/concepts/base-model">底模是什么</a>。反面信号是模型卡只有一句“效果很好”——连作者都说不清它是什么。</p><p>第 3 步，核对许可证。基座模型的许可证是“仅限非商用”，微调版继承同一授权，微调不改授权。你只在自己电脑上用，可以通过；如果打算接进收费服务，到这里就该停下换模型。</p><p>第 4 步，看文件与量化。文件列表里有 FP16 原始权重（约 16 GB）和一份 Q4 量化版（约 5 GB；量化指用更低精度的数字存储模型参数，换取更小体积）。你的显卡只有 8 GB 显存，选 Q4 版；同时核对文件名里的量化等级与说明一致，防止下到被改名重打包的版本。</p><p>第 5 步，翻社区反馈。讨论区有人报告“长对话后开始重复输出”，作者回复并更新了推荐参数；没有恶意行为的报告。——有具体问题的讨论比清一色叫好更有信息量；反馈当参考，不当担保。</p><p>第 6 步，记录存档。下载完成，当场记一行：模型名、发布页地址、版本号（commit）、许可证、量化等级、下载日期、推荐参数。三个月后出问题，先查这行记录。</p><p>哪一步偷懒，代价是什么：</p><table tabindex="0"><thead><tr><th>偷懒的步骤</th><th>可能的后果</th></tr></thead><tbody><tr><td>跳过发布者核对</td><td>装上来路不明的重打包版，轻则效果不对，重则夹带恶意内容</td></tr><tr><td>跳过模型卡</td><td>高估了模型能力，下载之后发现根本不适合你的任务</td></tr><tr><td>跳过许可证核对</td><td>服务上线后收到权利方函件，只能下线重做</td></tr><tr><td>跳过文件核对</td><td>下了 16 GB 原始权重，显存装不下，白等半小时下载</td></tr><tr><td>跳过社区反馈</td><td>社区早已报告的问题，你再踩一遍</td></tr><tr><td>跳过记录存档</td><td>“这个模型当时从哪下的”没人记得，复现与排错无从谈起</td></tr></tbody></table><h2 id="使用外部资源的原则" tabindex="-1">使用外部资源的原则 <a class="header-anchor" href="#使用外部资源的原则" aria-label="Permalink to &quot;使用外部资源的原则&quot;">​</a></h2><p>上一节是“用之前怎么筛”，这一节是筛过之后的使用习惯：</p><ul><li>判断不过关的资源不用；不因为“大家都在用”而放行。</li><li>不把未知来源的模型、数据、角色或素材直接用于公开或商业项目；先核实授权，再谈使用。</li><li>社区教程用来补充操作经验；涉及参数、下载和兼容性时，回到官方资料核对当前版本。</li><li>记录来源、版本、访问日期和关键配置；外部资源会更新或消失，你的记录才是稳定的复查依据。</li><li>转述或引用时注明出处和访问日期，让读的人也能复查。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“预印本等于定论”</strong>：预印本未经同行评审，结论可能被后续研究修正甚至推翻；引用前看有没有正式发表版本和复现结果。</li><li><strong>“Star 多等于可靠”</strong>：Star 衡量关注度，不衡量正确性；刷量、营销和“方便收藏”都会推高数字，安全漏洞和复现失败也常发生在热门项目上。</li><li><strong>“教程能跑通就等于理解了”</strong>：照抄命令只能得到一次成功，换个版本、换个模型就报错；能说清每一步在做什么、失败后从哪查起，才算理解。</li><li><strong>“收藏了链接等于有了资料”</strong>：链接会失效、页面会改版；真正可复用的是你自己的记录——来源、版本、关键参数，以及当时为什么选它。</li><li><strong>“官网内容永远有效”</strong>：官网也会过期——产品下线、API 改版、公告撤回都会发生；看官网要顺带看发布日期，遇到冲突以当前官方页面为准。</li><li><strong>“聚合站比官方文档好读，就以它为准”</strong>：聚合站内容经过转述，滞后和失真都常见；可以当入门线索，但参数和结论要回到官方来源核对。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-同一个模型名能搜到个人账号和组织账号两个版本-选哪个-为什么" tabindex="-1">1. 同一个模型名能搜到个人账号和组织账号两个版本，选哪个？为什么？ <a class="header-anchor" href="#_1-同一个模型名能搜到个人账号和组织账号两个版本-选哪个-为什么" aria-label="Permalink to &quot;1. 同一个模型名能搜到个人账号和组织账号两个版本，选哪个？为什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>优先选组织（官方）账号下的版本：发布者身份可以确认，模型卡、许可证和更新记录通常更完整。个人重打包版可能改动不明、授权不清；除非它明确说明改了什么且确有需要，否则不作为第一选择。</p></details><h3 id="_2-找到一篇讲新技术原理的文章-写得清楚易懂-怎么决定能不能直接引用它的结论" tabindex="-1">2. 找到一篇讲新技术原理的文章，写得清楚易懂，怎么决定能不能直接引用它的结论？ <a class="header-anchor" href="#_2-找到一篇讲新技术原理的文章-写得清楚易懂-怎么决定能不能直接引用它的结论" aria-label="Permalink to &quot;2. 找到一篇讲新技术原理的文章，写得清楚易懂，怎么决定能不能直接引用它的结论？&quot;">​</a></h3><details><summary>查看答案</summary><p>把它当线索，不当来源：顺着它找到原始论文或官方文档，核对结论是否一致、信息是否更新；涉及关键数字和参数时，以原始来源为准。多个二手来源互相引用不算独立验证——它们可能都出自同一篇预印本。</p></details><h3 id="_3-三个月前下载过一个微调模型-现在生成的结果和当时不一样-第一步做什么" tabindex="-1">3. 三个月前下载过一个微调模型，现在生成的结果和当时不一样，第一步做什么？ <a class="header-anchor" href="#_3-三个月前下载过一个微调模型-现在生成的结果和当时不一样-第一步做什么" aria-label="Permalink to &quot;3. 三个月前下载过一个微调模型，现在生成的结果和当时不一样，第一步做什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>先查当时记录下的来源、版本号和推荐参数——这正是下载后当场存档的意义。确认是模型版本变了、参数不同，还是运行工具更新所致，再回到发布页核对该版本的模型卡和更新说明。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>选择工具：</strong> <a href="/tools/common-tools">常用工具</a>帮助先判断需要哪类产品或框架。</li><li><strong>继续学习：</strong> <a href="/resources/tutorials">精选教程</a>从“知道网站”走到“跟着练”。</li><li><strong>随时查词：</strong> <a href="/glossary">术语表</a>解释文档和教程里的常见术语。</li></ul>',115)])])}const u=e(i,[["render",o]]);export{d as __pageData,u as default};
